escenas.drawCode:
drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const p = ease(seg(t, 0, 1));
const pFail = ease(seg(t, F.at('fracasan'), F.at('fracasan') + 0.5));

// Planilla vertical rota en tiza
ctx.save();
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.6;
const w = 58, h = 46, x0 = cx - w / 2, y0 = cy - h / 2 + 4;
rrect(x0, y0, w, h, 2);
ctx.stroke();

// Filas y columnas de celdas
for (let i = 1; i <= 5; i++) line(x0, y0 + (h / 6) * i, x0 + w, y0 + (h / 6) * i);
for (let j = 1; j <= 3; j++) line(x0 + (w / 4) * j, y0, x0 + (w / 4) * j, y0 + h);
ctx.restore();

// Celdas caóticas y errores
if (pFail > 0) {
  cross(cx - 12, cy - 6, 3.5 * pFail, pFail, C.warn);
  cross(cx + 12, cy + 6, 3.2 * pFail, pFail, C.warn);
  txt('#REF!', cx + 12, cy - 6, { size: 2.8, color: C.warn, family: FONT.mono, a: pFail });
  txt('NULL', cx - 12, cy + 6, { size: 2.8, color: C.muted, family: FONT.mono, a: pFail });
  bubble(cx + 20, cy - 16, 5 * pFail, '?', C.accent, pFail);
}

// Sello de fallo arriba
txt('80%', cx, cy - 24, { size: 7.5 * p, color: C.warn, w: 700 });

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const pLine = ease(seg(t, F.at('dividimos'), F.at('dividimos') + 0.6));
const pAna = ease(seg(t, F.at('analista'), F.at('analista') + 0.5));
const pDis = ease(seg(t, F.at('diseñador'), F.at('diseñador') + 0.5));

// Línea divisoria horizontal en formato vertical
if (pLine > 0) {
  ctx.save();
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 0.8;
  ctx.setLineDash([2, 2]);
  line(cx - 32, cy - 4, cx + 32, cy - 4);
  ctx.restore();
}

// Nivel superior: Data Analyst
if (pAna > 0) {
  const yA = cy - 22;
  person(cx - 14, yA - 4, 7 * pAna, C.accent2, pAna);
  magnifier(cx + 10, yA - 2, 5 * pAna, pAna);
  txt('DATA ANALYST', cx, yA + 9, { size: 3.2, color: C.ink, family: FONT.mono, a: pAna, w: 700 });
  txt('Rigor & Calidad', cx, yA + 13, { size: 2.6, color: C.muted, a: pAna });
}

// Nivel inferior: Dashboard Designer
if (pDis > 0) {
  const yD = cy + 14;
  person(cx - 14, yD - 4, 7 * pDis, C.accent, pDis);
  laptop(cx + 10, yD - 2, 7.5 * pDis, pDis, 0.4);
  txt('DASHBOARD DESIGNER', cx, yD + 9, { size: 3.2, color: C.ink, family: FONT.mono, a: pDis, w: 700 });
  txt('Data Honesty & UI', cx, yD + 13, { size: 2.6, color: C.muted, a: pDis });
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 8;
const pRaw = ease(seg(t, 0, 0.8));
const pClean = ease(seg(t, F.at('limpiando'), F.at('limpiando') + 0.6));
const pOk = ease(seg(t, F.at('rota'), F.at('rota') + 0.5));

// Planillas superiores
doc(cx - 16, cy - 24, 5 * pRaw, pRaw, 4);
doc(cx + 16, cy - 22, 5.5 * pRaw, pRaw, 5);

// Embudo vertical
ctx.save();
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.8;
ctx.beginPath();
ctx.moveTo(cx - 26, cy - 10);
ctx.lineTo(cx - 8, cy + 4);
ctx.lineTo(cx - 8, cy + 10);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx + 26, cy - 10);
ctx.lineTo(cx + 8, cy + 4);
ctx.lineTo(cx + 8, cy + 10);
ctx.stroke();
ctx.restore();

// Bloques Parquet compactos
if (pClean > 0) {
  for (let b = -1; b <= 1; b++) {
    for (let r = 0; r < 2; r++) {
      const bx = cx + b * 13, by = cy + 14 + r * 7;
      ctx.save();
      ctx.fillStyle = C.panel2;
      ctx.strokeStyle = C.accent2;
      ctx.lineWidth = 0.5;
      rrect(bx - 5, by - 2.5, 10, 5, 1.2);
      ctx.fill(); ctx.stroke();
      ctx.restore();
    }
  }
  txt('PARQUET STREAMING', cx, cy + 30, { size: 2.8, color: C.accent2, family: FONT.mono, a: pClean });
}

if (pOk > 0) {
  checkBadge(cx + 26, cy + 18, 5 * pOk, pOk);
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const pLock = ease(seg(t, F.at('dueño'), F.at('dueño') + 0.5));

// 5 tarjetas de KPI en lista vertical adaptada a móvil
const count = 5;
const cardW = 60, cardH = 8, gap = 2;
const startY = cy - 24;

for (let i = 0; i < count; i++) {
  const y = startY + i * (cardH + gap);
  const delay = i * 0.08;
  const pI = ease(seg(t, F.at('cinco') + delay, F.at('cinco') + delay + 0.4));
  if (pI <= 0) continue;

  ctx.save();
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = (i === 0) ? C.accent : C.line;
  ctx.lineWidth = 0.6;
  rrect(cx - cardW / 2, y, cardW, cardH, 2);
  ctx.fill(); ctx.stroke();
  ctx.restore();

  txt('KPI 0' + (i + 1), cx - cardW * 0.32, y + cardH / 2, { size: 2.8, color: C.accent, family: FONT.mono, a: pI, w: 700 });
  txt('f(x) = validated', cx, y + cardH / 2, { size: 2.3, color: C.muted, family: FONT.mono, a: pI });

  if (pLock > 0) {
    padlock(cx + cardW * 0.35, y + cardH / 2 - 1.5, 2.2 * pLock, 1, pLock);
  }
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const pBuild = ease(seg(t, 0, 0.8));
const pSpark = ease(seg(t, F.at('vectoriales'), F.at('vectoriales') + 0.6));

// Marco de pantalla móvil
ctx.save();
ctx.strokeStyle = C.line;
ctx.fillStyle = C.panel;
ctx.lineWidth = 0.7;
rrect(cx - 32, cy - 32, 64, 64, 4);
ctx.fill(); ctx.stroke();

// KPIs superiores en 2 columnas
for (let k = 0; k < 2; k++) {
  const kx = cx - 15 + k * 30, ky = cy - 24;
  ctx.fillStyle = C.panel2;
  rrect(kx - 12, ky - 5, 24, 10, 1.5);
  ctx.fill();
  const vals = ['42 850', '98.4%'];
  txt(vals[k], kx, ky, { size: 3.2 * pBuild, color: C.ink, family: FONT.mono, w: 700 });
}

// Gráfico central SVG
const gx = cx - 26, gy = cy - 12, gw = 52, gh = 22;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.4;
line(gx, gy + gh, gx + gw, gy + gh);
line(gx, gy, gx, gy + gh);

if (pSpark > 0) {
  ctx.strokeStyle = C.accent2;
  ctx.lineWidth = 1;
  ctx.beginPath();
  const pts = [[0, 18], [12, 14], [24, 16], [36, 7], [48, 9], [52, 4]];
  pts.forEach(([px, py], idx) => {
    const x = gx + (px / 52) * gw;
    const y = gy + (py / 22) * gh;
    idx === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.stroke();
}

// Lista inferior ordenada
for (let r = 0; r < 3; r++) {
  const ry = cy + 16 + r * 4.5;
  ctx.fillStyle = C.muted;
  ctx.fillRect(cx - 24, ry, 36 * (1 - r * 0.25) * pBuild, 2);
}
ctx.restore();

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const pAlert = ease(seg(t, F.at('enciende'), F.at('enciende') + 0.4));

// Gráficos de viñeta en formato vertical apilado
const rows = 3;
for (let i = 0; i < rows; i++) {
  const y = cy - 18 + i * 14;
  const isProblem = (i === 1);

  ctx.save();
  ctx.fillStyle = C.panel;
  rrect(cx - 30, y - 4, 60, 8, 1.5);
  ctx.fill();

  const valW = isProblem ? 18 : 38;
  ctx.fillStyle = (isProblem && pAlert > 0) ? C.warn : C.muted;
  rrect(cx - 28, y - 2.5, valW, 5, 1);
  ctx.fill();

  // Línea de meta
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 0.8;
  line(cx + 6, y - 3.5, cx + 6, y + 3.5);

  if (isProblem && pAlert > 0) {
    ring(cx + 20, y, 3.8 * pAlert, pAlert, C.accent, 0.8);
    arrow(cx + 8, y, cx + 16, y, pAlert, C.accent, 0.8);
    txt('ACT', cx + 20, y, { size: 2.2, color: C.accent, family: FONT.mono, w: 700 });
  }
  ctx.restore();
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const pIn = ease(seg(t, 0, 0.7));
const pBoard = ease(seg(t, F.at('directorio'), F.at('directorio') + 0.6));
const pCheck = ease(seg(t, F.at('decisión'), F.at('decisión') + 0.5));

// Conector vertical
arrow(cx, cy - 28, cx, cy - 18, pIn, C.accent2, 1);

// Carpeta ejecutiva central
if (pBoard > 0) {
  const bx = cx, by = cy + 2;
  ctx.save();
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 0.7;
  rrect(bx - 26, by - 16, 52, 32, 2);
  ctx.fill(); ctx.stroke();

  txt('DECISIÓN EJECUTIVA', bx, by - 10, { size: 2.6, color: C.accent, family: FONT.mono, w: 700 });
  line(bx - 20, by - 6, bx + 20, by - 6);

  for (let c = 0; c < 3; c++) {
    const cyRow = by - 1 + c * 6.5;
    if (pCheck > 0) check(bx - 18, cyRow, 2 * pCheck, pCheck);
    ctx.fillStyle = C.ink;
    ctx.fillRect(bx - 12, cyRow - 0.7, 30 * pBoard, 1.6);
  }
  ctx.restore();
}

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy - 10;
const pFlow = ease(seg(t, 0, 1));
const pBadge = ease(seg(t, F.at('transparente'), F.at('transparente') + 0.5));

// 4 estaciones en flujo vertical de arriba hacia abajo
const steps = ['1. INGESTA', '2. GOBERNANZA', '3. DISEÑO UI', '4. DECISIÓN'];
for (let s = 0; s < 4; s++) {
  const sy = cy - 25 + s * 14;
  ctx.save();
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 0.7;
  rrect(cx - 20, sy - 4.5, 40, 9, 2);
  ctx.fill(); ctx.stroke();

  txt(steps[s], cx, sy, { size: 2.6 * pFlow, color: C.ink, family: FONT.mono, w: 700 });
  ctx.restore();

  if (s < 3) {
    arrow(cx, sy + 4.5, cx, sy + 9.5, pFlow * 0.7, C.line, 0.7);
  }
}

if (pBadge > 0) {
  checkBadge(cx + 26, cy + 17, 5 * pBadge, pBadge);
  txt('DATA HONESTY', cx, cy + 28, { size: 3 * pBadge, color: C.ok, family: FONT.mono, w: 700, a: pBadge });
}
